+    });
+
+    test('origin fallback failure falls back to merge-base — exact commands', function() {
+        var h = makeHarness({
+            'git rev-parse --is-shallow-repository': 'false\nCOMMAND_EXIT_CODE=0',
+            'git diff main...feature/x': function() { throw new Error('fail 1'); },
