+            'git diff abc123def...feature/x': 'mb diff\nCOMMAND_EXIT_CODE=0'
+        });
+
+        var diff = run(h, 'main', 'feature/x');
+
+        assert.equal(diff, 'mb diff');
+        assert.deepEqual(h.commandStrings(), [
+            EXPLICIT_FETCH_MAIN,
+            'git rev-parse --is-shallow-repository',
